import { NextResponse } from "next/server";
import { publishVariant } from "@/lib/connectors/taboolaCreatives";
import { getConnection } from "@/lib/store";

export const dynamic = "force-dynamic";
export const maxDuration = 120;

/** Only images generated by fal.ai can be published (the server downloads them). */
const ALLOWED_IMAGE_HOST = /(^|\.)fal\.media$|^storage\.googleapis\.com$/;

/**
 * { accountId, campaignId, url, title, imageUrl } → creates the ad PAUSED in the
 * same Taboola campaign, with the same landing URL (the RedTrack link).
 */
export async function POST(req: Request) {
  const b = (await req.json()) as { accountId?: string; campaignId?: string; url?: string; title?: string; imageUrl?: string };
  if (!b.accountId || !b.campaignId || !b.url || !b.title?.trim() || !b.imageUrl) {
    return NextResponse.json({ error: "Faltam dados para subir o anúncio." }, { status: 400 });
  }
  let host = "";
  try {
    const u = new URL(b.imageUrl);
    host = u.protocol === "https:" ? u.hostname : "";
  } catch {}
  if (!ALLOWED_IMAGE_HOST.test(host)) return NextResponse.json({ error: "Imagem não reconhecida." }, { status: 400 });

  const conn = await getConnection(b.accountId);
  if (!conn || conn.provider !== "taboola") return NextResponse.json({ error: "Conta Taboola não encontrada." }, { status: 404 });
  try {
    const item = await publishVariant(conn.credentials, b.campaignId, b.url, b.title.trim().slice(0, 100), b.imageUrl);
    return NextResponse.json({ item });
  } catch (e) {
    return NextResponse.json({ error: (e as Error).message }, { status: 502 });
  }
}
